(1, 1, 'Một người bình luận WordPress', 'wapuu@wordpress.example', 'https://vi.wordpress.org/', '', '2026-05-08 08:43:11', '2026-05-08 08:43:11', 'Xin chào, đây là một bình luận.\nĐể bắt đầu kiểm duyệt, chỉnh sửa và xóa nhận xét, vui lòng truy cập màn hình Nhận xét trong trang quản trị.\nHình đại diện của người bình luận đến từ <a href=\"https://gravatar.com/\">Gravatar</a>.', 0, '1', '', 'comment', 0, 0),
(2, 463, 'WooCommerce', '', '', '', '2026-05-10 01:32:34', '2026-05-10 01:32:34', 'Stock hold of 60 minutes applied to: <br>- Iphone 17 Promax - 2TB, Navi Blue (ip17prm)<span class=\"description\"></span> &times; 1', 0, '1', 'WooCommerce', 'order_note', 0, 0),
(3, 463, 'WooCommerce', '', '', '', '2026-05-10 01:32:35', '2026-05-10 01:32:35', 'Stock levels reduced: Iphone 17 Promax - 2TB, Navi Blue (100&rarr;99), Iphone 12 (100&rarr;99)', 0, '1', 'WooCommerce', 'order_note', 0, 0),
(4, 463, 'WooCommerce', '', '', '', '2026-05-10 01:32:35', '2026-05-10 01:32:35', 'Payment to be made upon delivery. Order status changed from Pending payment to Processing.', 0, '1', 'WooCommerce', 'order_note', 0, 0),
(5, 464, 'WooCommerce', '', '', '', '2026-05-10 01:33:57', '2026-05-10 01:33:57', 'Stock hold of 60 minutes applied to: <br>- Iphone 11 (ip11)<span class=\"description\">Color: Black, Storage: 128GB, Model: iPhone 11</span> &times; 1', 0, '1', 'WooCommerce', 'order_note', 0, 0),
