(480, 1, '2026-05-11 04:12:01', '2026-05-11 04:12:01', '<ul>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,0,0\">Flagship quyền năng nhất thế giới Android</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,1,0\">Màn hình Dynamic AMOLED 2X 6.9 inch phẳng tuyệt đối</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,2,0\">Chip Snapdragon 8 Gen 5 cực mạnh cho gaming và AI</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,3,0\">Camera 200MP với khả năng zoom xa 100x chất lượng cao</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,4,0\">Khung viền Titanium sang trọng và siêu bền</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,5,0\">Tích hợp bút S Pen đa năng trong thân máy</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"4,1,1,6,0\">Pin 5000mAh hỗ trợ sạc siêu nhanh 45W</p>\r\n</li>\r\n</ul>', 'Samsung Galaxy S26 Ultra', '', 'publish', 'open', 'closed', '', 'samsung-galaxy-s26-ultra', '', '', '2026-05-11 04:20:53', '2026-05-11 04:20:53', '', 0, 'http://localhost/PMMNM/?post_type=product&#038;p=480', 0, 'product', '', 0),
