(582, 1, '2026-05-11 08:26:54', '2026-05-11 08:26:54', '{\n    \"sidebars_widgets[header-widget-1]\": {\n        \"value\": [\n            \"block-8\"\n        ],\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:19:45\"\n    },\n    \"astra-settings[header-desktop-items]\": {\n        \"value\": {\n            \"popup\": {\n                \"popup_content\": [\n                    \"mobile-menu\"\n                ]\n            },\n            \"above\": {\n                \"above_left\": [\n                    \"logo\",\n                    \"menu-1\"\n                ],\n                \"above_left_center\": [],\n                \"above_center\": [],\n                \"above_right_center\": [],\n                \"above_right\": [\n                    \"account\",\n                    \"woo-cart\"\n                ]\n            },\n            \"primary\": {\n                \"primary_left\": [],\n                \"primary_left_center\": [],\n                \"primary_center\": [],\n                \"primary_right_center\": [],\n                \"primary_right\": [\n                    \"widget-1\"\n                ]\n            },\n            \"below\": {\n                \"below_left\": [],\n                \"below_left_center\": [],\n                \"below_center\": [],\n                \"below_right_center\": [],\n                \"below_right\": []\n            },\n            \"flag\": true\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:20:20\"\n    },\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- wp:search {\\\"label\\\":\\\"T\\u00ecm ki\\u1ebfm\\\",\\\"placeholder\\\":\\\"B\\u1ea1n c\\u1ea7n t\\u00ecm g\\u00ec \\\",\\\"buttonText\\\":\\\"T\\u00ecm \\\"} /-->\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:26:54\"\n    },\n    \"custom_css[astra]\": {\n        \"value\": \"/* L\\u00e0m \\u0111\\u1eb9p \\u00f4 t\\u00ecm ki\\u1ebfm Widget */\\n.widget_search .search-form {\\n    display: flex;\\n    border: 2px solid #ff0000 !important; /* Vi\\u1ec1n \\u0111\\u1ecf r\\u1ef1c */\\n    border-radius: 30px !important;       /* Bo g\\u00f3c tr\\u00f2n x\\u1ecbn */\\n    overflow: hidden;\\n    background: #fff;\\n    max-width: 450px; /* \\u0110\\u1ed9 d\\u00e0i \\u00f4 t\\u00ecm ki\\u1ebfm */\\n    margin: 0 auto;\\n}\\n\\n.widget_search .search-field {\\n    border: none !important;\\n    padding: 8px 15px !important;\\n    outline: none !important;\\n    width: 100%;\\n}\\n\\n.widget_search .search-submit {\\n    background-color: #ff0000 !important; /* N\\u00fat t\\u00ecm ki\\u1ebfm m\\u00e0u \\u0111\\u1ecf */\\n    color: #fff !important;\\n    border: none;\\n    padding: 0 20px;\\n    cursor: pointer;\\n    text-transform: uppercase;\\n    font-weight: bold;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:21:56\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'ff006542-523d-479b-871b-2689a631e1ec', '', '', '2026-05-11 08:26:54', '2026-05-11 08:26:54', '', 0, 'http://localhost/PMMNM/?p=582', 0, 'customize_changeset', '', 0),
(583, 1, '2026-05-11 08:26:54', '2026-05-11 08:26:54', '/* Ép nút và ô nhập không được xuống dòng */\n.wp-block-search__inside-wrapper {\n    display: flex !important;\n    flex-wrap: nowrap !important; /* Tuyệt đối không cho xuống dòng */\n    align-items: stretch !important;\n}\n\n/* Nới rộng nút một chút để chữ không bị đứng hình */\n.wp-block-search__button {\n    white-space: nowrap !important; /* Chữ phải nằm trên 1 hàng */\n    min-width: 60px !important;    /* Độ rộng tối thiểu cho nút */\n    padding: 0 15px !important;\n}\n\n/* Chỉnh lại ô nhập cho cân đối */\n.wp-block-search__input {\n    flex-grow: 1 !important;\n    min-width: 0 !important; /* Để nó không đẩy nút ra ngoài */\n}\n/* 1. Ép chiều cao cố định cho khung sản phẩm */\n.woocommerce ul.products li.product {\n    display: flex;\n    flex-direction: column;\n    background: #fff;\n    padding: 15px;\n    border: 1px solid #eee;\n    border-radius: 8px;\n    height: 100%;\n}\n\n/* 2. Ép ảnh sản phẩm bằng nhau và không bị méo */\n.woocommerce ul.products li.product img {\n    height: 200px !important; /* Bạn có thể chỉnh số này tùy ý */\n    object-fit: contain !important; \n    margin-bottom: 15px;\n}\n\n/* 3. Ép tên sản phẩm luôn chiếm 2 dòng (để không bị lệch giá) */\n.woocommerce ul.products li.product .woocommerce-loop-product__title {\n    min-height: 40px; \n    line-height: 20px;\n    margin-bottom: 10px;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n}\n\n/* 4. Đẩy nút Add to cart xuống tận cùng cho thẳng hàng */\n.woocommerce ul.products li.product .button {\n    margin-top: auto !important;\n    align-self: center;\n}', 'astra', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2026-05-11 09:06:29', '2026-05-11 09:06:29', '', 0, 'http://localhost/PMMNM/?p=583', 0, 'custom_css', '', 0),
(584, 1, '2026-05-11 08:26:54', '2026-05-11 08:26:54', '/* Làm đẹp ô tìm kiếm Widget */\n.widget_search .search-form {\n    display: flex;\n    border: 2px solid #ff0000 !important; /* Viền đỏ rực */\n    border-radius: 30px !important;       /* Bo góc tròn xịn */\n    overflow: hidden;\n    background: #fff;\n    max-width: 450px; /* Độ dài ô tìm kiếm */\n    margin: 0 auto;\n}\n\n.widget_search .search-field {\n    border: none !important;\n    padding: 8px 15px !important;\n    outline: none !important;\n    width: 100%;\n}\n\n.widget_search .search-submit {\n    background-color: #ff0000 !important; /* Nút tìm kiếm màu đỏ */\n    color: #fff !important;\n    border: none;\n    padding: 0 20px;\n    cursor: pointer;\n    text-transform: uppercase;\n    font-weight: bold;\n}', 'astra', '', 'inherit', 'closed', 'closed', '', '583-revision-v1', '', '', '2026-05-11 08:26:54', '2026-05-11 08:26:54', '', 583, 'http://localhost/PMMNM/?p=584', 0, 'revision', '', 0),
(585, 1, '2026-05-11 08:27:13', '2026-05-11 08:27:13', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* L\\u00e0m \\u0111\\u1eb9p \\u00f4 t\\u00ecm ki\\u1ebfm Widget */\\n.widget_search .search-form {\\n    display: flex;\\n    border: 2px solid #ff0000 !important; /* Vi\\u1ec1n \\u0111\\u1ecf r\\u1ef1c */\\n    border-radius: 30px !important;       /* Bo g\\u00f3c tr\\u00f2n x\\u1ecbn */\\n    overflow: hidden;\\n    background: #fff;\\n    max-width: 450px; /* \\u0110\\u1ed9 d\\u00e0i \\u00f4 t\\u00ecm ki\\u1ebfm */\\n    margin: 0 auto;\\n}\\n\\n.widget_search .search-field {\\n    border: none !important;\\n    padding: 8px 15px !important;\\n    outline: none !important;\\n    width: 100%;\\n}\\n\\n.widget_search .search-submit {\\n    background-color: #ff0000 !important; /* N\\u00fat t\\u00ecm ki\\u1ebfm m\\u00e0u \\u0111\\u1ecf */\\n    color: #fff !important;\\n    border: none;\\n    padding: 0 20px;\\n    cursor: pointer;\\n    text-transform: uppercase;\\n    font-weight: bold;\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:27:13\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '8dc8bb3a-34ed-44d6-8d7c-695219bbddb6', '', '', '2026-05-11 08:27:13', '2026-05-11 08:27:13', '', 0, 'http://localhost/PMMNM/?p=585', 0, 'customize_changeset', '', 0),
(586, 1, '2026-05-11 08:29:05', '2026-05-11 08:29:05', '{\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\u0110\\u01b0a \\u00f4 nh\\u1eadp v\\u00e0 n\\u00fat T\\u00ecm l\\u00ean c\\u00f9ng 1 h\\u00e0ng */\\n.widget_search .wp-block-search__inside-wrapper {\\n    display: flex !important;\\n    border: 2px solid #ff0000 !important; /* Vi\\u1ec1n \\u0111\\u1ecf r\\u1ef1c */\\n    border-radius: 30px !important;       /* Bo g\\u00f3c tr\\u00f2n */\\n    overflow: hidden;\\n    background: #fff;\\n    max-width: 400px;\\n}\\n\\n/* X\\u00f3a vi\\u1ec1n m\\u1eb7c \\u0111\\u1ecbnh c\\u1ee7a \\u00f4 ch\\u1eef */\\n.widget_search .wp-block-search__input {\\n    border: none !important;\\n    padding: 10px 15px !important;\\n    outline: none !important;\\n    flex-grow: 1;\\n}\\n\\n/* L\\u00e0m \\u0111\\u1eb9p n\\u00fat T\\u00ecm */\\n.widget_search .wp-block-search__button {\\n    background-color: #ff0000 !important; /* N\\u00fat m\\u00e0u \\u0111\\u1ecf */\\n    color: #fff !important;\\n    border: none !important;\\n    padding: 0 20px !important;\\n    margin: 0 !important;\\n    cursor: pointer;\\n}\\n\\n/* \\u1ea8n ch\\u1eef \\\"T\\u00ecm ki\\u1ebfm\\\" th\\u1eeba ph\\u00eda tr\\u00ean */\\n.widget_search .wp-block-search__label {\\n    display: none;\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:29:05\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '7e1ca577-4d98-4fb4-bc2d-41f4ddca7ae4', '', '', '2026-05-11 08:29:05', '2026-05-11 08:29:05', '', 0, 'http://localhost/PMMNM/?p=586', 0, 'customize_changeset', '', 0),
(587, 1, '2026-05-11 08:29:05', '2026-05-11 08:29:05', '/* Đưa ô nhập và nút Tìm lên cùng 1 hàng */\n.widget_search .wp-block-search__inside-wrapper {\n    display: flex !important;\n    border: 2px solid #ff0000 !important; /* Viền đỏ rực */\n    border-radius: 30px !important;       /* Bo góc tròn */\n    overflow: hidden;\n    background: #fff;\n    max-width: 400px;\n}\n\n/* Xóa viền mặc định của ô chữ */\n.widget_search .wp-block-search__input {\n    border: none !important;\n    padding: 10px 15px !important;\n    outline: none !important;\n    flex-grow: 1;\n}\n\n/* Làm đẹp nút Tìm */\n.widget_search .wp-block-search__button {\n    background-color: #ff0000 !important; /* Nút màu đỏ */\n    color: #fff !important;\n    border: none !important;\n    padding: 0 20px !important;\n    margin: 0 !important;\n    cursor: pointer;\n}\n\n/* Ẩn chữ \"Tìm kiếm\" thừa phía trên */\n.widget_search .wp-block-search__label {\n    display: none;\n}\n', 'astra', '', 'inherit', 'closed', 'closed', '', '583-revision-v1', '', '', '2026-05-11 08:29:05', '2026-05-11 08:29:05', '', 583, 'http://localhost/PMMNM/?p=587', 0, 'revision', '', 0),
(588, 1, '2026-05-11 08:36:08', '2026-05-11 08:36:08', '{\n    \"widget_block[8]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- wp:search {\\\"label\\\":\\\"T\\u00ecm ki\\u1ebfm\\\",\\\"placeholder\\\":\\\"B\\u1ea1n c\\u1ea7n t\\u00ecm g\\u00ec \\\",\\\"width\\\":251,\\\"widthUnit\\\":\\\"px\\\",\\\"buttonText\\\":\\\"T\\u00ecm \\\"} /-->\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:32:00\"\n    },\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\u00c9p n\\u00fat v\\u00e0 \\u00f4 nh\\u1eadp kh\\u00f4ng \\u0111\\u01b0\\u1ee3c xu\\u1ed1ng d\\u00f2ng */\\n.wp-block-search__inside-wrapper {\\n    display: flex !important;\\n    flex-wrap: nowrap !important; /* Tuy\\u1ec7t \\u0111\\u1ed1i kh\\u00f4ng cho xu\\u1ed1ng d\\u00f2ng */\\n    align-items: stretch !important;\\n}\\n\\n/* N\\u1edbi r\\u1ed9ng n\\u00fat m\\u1ed9t ch\\u00fat \\u0111\\u1ec3 ch\\u1eef kh\\u00f4ng b\\u1ecb \\u0111\\u1ee9ng h\\u00ecnh */\\n.wp-block-search__button {\\n    white-space: nowrap !important; /* Ch\\u1eef ph\\u1ea3i n\\u1eb1m tr\\u00ean 1 h\\u00e0ng */\\n    min-width: 60px !important;    /* \\u0110\\u1ed9 r\\u1ed9ng t\\u1ed1i thi\\u1ec3u cho n\\u00fat */\\n    padding: 0 15px !important;\\n}\\n\\n/* Ch\\u1ec9nh l\\u1ea1i \\u00f4 nh\\u1eadp cho c\\u00e2n \\u0111\\u1ed1i */\\n.wp-block-search__input {\\n    flex-grow: 1 !important;\\n    min-width: 0 !important; /* \\u0110\\u1ec3 n\\u00f3 kh\\u00f4ng \\u0111\\u1ea9y n\\u00fat ra ngo\\u00e0i */\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-05-11 08:36:01\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'f1a9d333-4327-4634-b4a0-e626c9f0563e', '', '', '2026-05-11 08:36:08', '2026-05-11 08:36:08', '', 0, 'http://localhost/PMMNM/?p=588', 0, 'customize_changeset', '', 0),
